import type { EventPayload } from '@almadar/core';
import type { Run } from '../types/entities';
import type { LoopANSWEREDPayload, LoopCALL_TOOLPayload, LoopFINALPayload, LoopOBSERVEDPayload, LoopTOOL_CHOSENPayload, LoopTOOL_RESULTPayload } from '../types/events';

export class Loop {
  state: string = "planning";
  entity: Run;
  readonly ports: Record<string, (...args: EventPayload[string][]) => void>;
  readonly config = {};
  readonly emitted: Array<{ event: string; payload: EventPayload }> = [];

  constructor(entity: Run, ports: Record<string, (...args: EventPayload[string][]) => void> = {}, config: Partial<Loop['config']> = {}) {
    this.entity = entity;
    this.ports = ports;
    this.config = { ...this.config, ...config };
  }

  emit(event: string, payload: EventPayload): void {
    this.emitted.push({ event, payload });
  }

  callPort(name: string, ...args: EventPayload[string][]): void {
    const port = this.ports[name];
    if (port === undefined) throw new Error('no port named ' + name);
    port(...args);
  }

  onInit(): void {
    if (this.state === "planning") {
      this.state = "planning";
    } else if (this.state === "acting") {
      this.state = "acting";
    } else if (this.state === "done") {
      this.state = "done";
    }
  }

  onToolChosen(payload: LoopTOOL_CHOSENPayload): void {
    if (this.state === "planning" && ((this.entity.steps ?? 0) < 5)) {
      this.entity.steps = ((this.entity.steps ?? 0) + 1);
      this.emit("CALL_TOOL", ({ name: payload.name, input: payload.input } satisfies LoopCALL_TOOLPayload));
      this.state = "acting";
    } else if (this.state === "planning" && ((this.entity.steps ?? 0) >= 5)) {
      this.entity.answer = "step budget reached";
      this.emit("ANSWERED", ({ answer: (this.entity.answer ?? "") } satisfies LoopANSWEREDPayload));
      this.state = "done";
    }
  }

  onFinal(payload: LoopFINALPayload): void {
    if (this.state === "planning") {
      this.entity.answer = payload.text;
      this.emit("ANSWERED", ({ answer: (this.entity.answer ?? "") } satisfies LoopANSWEREDPayload));
      this.state = "done";
    }
  }

  onToolResult(payload: LoopTOOL_RESULTPayload): void {
    if (this.state === "acting") {
      this.entity.observations = [...(this.entity.observations ?? []), payload.output];
      this.emit("OBSERVED", ({ output: payload.output } satisfies LoopOBSERVEDPayload));
      this.state = "planning";
    }
  }
}

